/// <summary>
/// Initializes form.
/// </summary>
public void init()
{
    super();

    filterFromDate.dateValue(DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone()));
    filterToDate.dateValue(DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone()));
}

/// <summary>
/// Close ok.
/// </summary>
public void closeOk()
{
    if (element.args()
        &&  element.args().caller()
        &&  element.args().caller() is FormRun)
    {
        FormRun formRun = element.args().caller();

        this.applyRanges(formRun);
    }

    super();
}

/// <summary>
/// Validates dates.
/// </summary>
/// <returns>true if the date is valid otherwise false</returns>
public boolean validateDate()
{
    boolean ret = true;

    if (filterFromDate.dateValue() > filterToDate.dateValue())
    {
        ret = checkFailed("@MET:ConfirmShipDateError");
    }

    return ret;
}

/// <summary>
/// Applies ranges.
/// </summary>
/// <param name = "_formRun">FormRun.</param>
public void applyRanges(FormRun _formRun)
{
    FormDataSource fds = _formRun.dataSource(formDataSourceStr(METTMSProcessingStatus, METTMSProcessingStatus));
    QueryBuildDataSource qbds = fds.queryBuildDataSource();

    if (qbds)
    {
        qbds.clearRanges();

        if (enum2Str(METTMSOrderType::None) != filterOrderType.valueStr())
        {
            qbds.addRange(fieldNum(METTMSProcessingStatus, OrderType)).value(filterOrderType.valueStr());
        }

        qbds.addRange(fieldNum(METTMSProcessingStatus, CreatedDateTime)).value(SysQueryRangeUtil::dateRange(filterFromDate.dateValue(), filterToDate.dateValue()));
    }

    fds.executeQuery();
}

/// <summary>
/// Modifies from date.
/// </summary>
/// <returns>True, if valid; otherwise, false.</returns>
public boolean modified()
{
    boolean ret;

    ret = super();
    ret = ret && element.validateDate();

    return ret;
}

/// <summary>
/// Modifies from date.
/// </summary>
/// <returns>True, if valid; otherwise, false.</returns>
public boolean modified()
{
    boolean ret;

    ret = super();
    ret = ret && element.validateDate();

    return ret;
}
